def parse_trajectory(trajectory):
    thoughts = 0
    tool_calls = 0
    has_answer = False
    for step in trajectory:
        if step.get("role") == "assistant":
            if "thought" in step:
                thoughts += 1
            if step.get("answer"):
                has_answer = True
        elif step.get("role") == "tool":
            tool_calls += 1
    return thoughts, tool_calls, has_answer

