def check_role_overlap(roles):
    overlaps = []
    names = list(roles.keys())
    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            a, b = names[i], names[j]
            common = [k for k in roles[a] if k in roles[b]]
            if common:
                overlaps.append((a, b, common))
    return overlaps

