def slim_state(state, keep_facts):
    return {
        "control": {
            "phase": state["control"]["phase"],
            "attempts": state["control"].get("attempts", 0),
        },
        "facts": {k: state["facts"][k] for k in keep_facts if k in state["facts"]},
        "meta": {"run_id": state["meta"]["run_id"]},
    }

